# Cuentos de Estudios Sociales de 6.º (1 a 4)
from personajes6 import *

CUENTOS = [
dict(area="sociales", n=1, slug="time-capsule", std="SS.6-8.H.3.LC",
  std_texto="classify the kinds of historical sources (primary and secondary) and explain what each one can and cannot tell us about the past.",
  titulo="The box from 1976", titulo_es="La caja de 1976",
  entrada="A story about a time capsule and the different kinds of sources historians use.",
  entrada_es="Un cuento sobre una cápsula del tiempo y los distintos tipos de fuentes que usan los historiadores.",
  tema="Historians learn from primary and secondary sources", tema_es="Los historiadores aprenden de fuentes primarias y secundarias",
  descripcion="A Grade 6 social studies story: a class opens a time capsule from 1976 and learns to tell primary sources from secondary sources. With key words, glossary, questions and optional help in Spanish.",
  alt="In the school library, Ms. Haddad lifts a dusty metal box while Daniel holds an old cassette tape, Selena reads a yellowed letter and Athena looks at a black-and-white photo.",
  escena=f"A sunny school library in Chicago: on a big wooden table sits an old dented metal box with its lid open; {P_HADDAD}, lifts a faded folded newspaper out of the box; {DANIEL}, holds up an old cassette tape and looks puzzled; {SELENA}, reads a yellowed handwritten letter; {ATHENA}, studies a small black-and-white photograph of children in front of a brick school",
  palabras=[
    ("historian","historian","A person who studies the past and explains what happened, using evidence.","historiador o historiadora","Una persona que estudia el pasado y explica lo que pasó usando evidencia."),
    ("primary","primary source","Something made by a person who was there at the time, like a letter, a photo or a diary.","fuente primaria","Algo hecho por una persona que estuvo allí en ese momento, como una carta, una foto o un diario."),
    ("secondary","secondary source","Something made later by someone who was not there, who studied other sources, like a history book.","fuente secundaria","Algo hecho después por alguien que no estuvo allí y que estudió otras fuentes, como un libro de historia."),
    ("artifact","artifact","An object made or used by people in the past, like a tool, a toy or a coin.","artefacto","Un objeto hecho o usado por personas en el pasado, como una herramienta, un juguete o una moneda."),
    ("perspective","perspective","The way one person sees an event, based on who they are and what they experienced.","perspectiva (punto de vista)","La manera en que una persona ve un suceso, según quién es y lo que vivió."),
    ("evidence","evidence","Facts or objects that help prove an idea about the past is true.","evidencia","Datos u objetos que ayudan a demostrar que una idea sobre el pasado es verdadera.")],
  parrafos=[
    '''For the school's 100th birthday, the principal brought a dusty metal box to the library. "This time capsule was sealed by sixth graders in 1976," she said, "and today, sixth graders get to open it." Ms. Haddad smiled at her class. "Today, you are not students. You are [[historian|historians]]."''',
    '''The lid creaked open. On top was a letter in neat cursive. Selena read it aloud: "Dear future students, today our class planted a tree for America's 200th birthday. I hope you still have recess." {{a|"This letter is a [[primary|primary source]]," said Ms. Haddad. "It was written by someone who was there, at the time."}}''',
    '''Daniel pulled out a small plastic rectangle with two holes and a brown ribbon inside. "What is this?" "A cassette tape," laughed Ms. Haddad. "People recorded music and voices on it." {{b|"It's also an [[artifact|artifact]], an object people used. Artifacts tell us how people lived, even when nobody wrote about them."}}''',
    '''Next came a black-and-white photo of children standing in front of a brick school. Athena held it next to the window and gasped. "That's our school! But there's no gym, and the street has no trees." Ms. Haddad nodded. "A photo is a primary source too. It shows us what changed and what stayed the same."''',
    '''At the bottom of the box was a thin booklet called The History of Our Neighborhood, written by a teacher in 1975. It told stories from the 1920s and 1930s. {{c|"This is a [[secondary|secondary source]]," said Ms. Haddad. "The teacher wasn't alive in the 1920s. She studied old newspapers and interviews, and then she wrote about them."}}''',
    '''Israel frowned. "So secondary sources are worse?" "Not worse, just different," said Ms. Haddad. "A secondary source can explain the big picture. A primary source gives you the voice of one person." {{d|Then she held up two more letters from the capsule. One boy wrote that 1976 was the best year ever. A girl wrote that her family had just moved and she missed her old friends. "Same school, same year, two different [[perspective|perspectives]]."}}''',
    '''"So which one is true?" asked Sophia. "Both can be true," said Ms. Haddad. {{e|"That's why historians never trust just one source. They compare many pieces of [[evidence|evidence]], they ask who made each one and why, and then they build an explanation."}}''',
    '''Before the bell rang, the class decided to make their own time capsule for 2076. Daniel wanted to put in his phone. "You can't," said Selena. "You need it." So he wrote a letter instead: Dear future students, we also hope you still have recess.'''],
  preguntas=[
    ("a","Why is the letter from 1976 a primary source?","¿Por qué la carta de 1976 es una fuente primaria?",
     ["It was written by someone who was there","It was written in neat cursive letters","It was found at the top of the box"],0,
     "The letter is a primary source because it was written by a student who was there, at the time."),
    ("b","What can an artifact like the cassette tape tell historians?","¿Qué les puede decir a los historiadores un artefacto como el casete?",
     ["The exact words people said in 1976","How people lived, even without writing","Which students were in the class"],1,
     "Artifacts are objects people used, and they show how people lived, even when nobody wrote about it."),
    ("c","Why is the 1975 neighborhood booklet a secondary source?","¿Por qué el folleto del barrio de 1975 es una fuente secundaria?",
     ["It was printed on thin, cheap paper","It was hidden at the bottom of the box","Its author studied older sources"],2,
     "The teacher who wrote it was not alive in the 1920s; she studied old newspapers and interviews and then wrote about them."),
    ("d","What did the two letters from the same year show?","¿Qué mostraron las dos cartas del mismo año?",
     ["That one of the students was lying","That people can see the same time differently","That 1976 was a terrible year for the school"],1,
     "Same school, same year, but two different perspectives: one boy loved the year, and a girl missed her old friends."),
    ("e","Why do historians compare many sources?","¿Por qué los historiadores comparan muchas fuentes?",
     ["Teachers ask them to read a lot of books","Old sources are usually full of mistakes","One source alone can't show the whole story"],2,
     "Historians compare many pieces of evidence and ask who made each one and why, because one source shows only part of the story.")],
  reto=dict(tipo="Sort the sources", tipo_es="Clasifica las fuentes",
    pregunta="Sort these sources into primary and secondary: a diary written in 1918, a website about the 1918 flu written last year, a photo of a 1918 hospital, and a textbook chapter about the 1900s. Then explain the rule you used.",
    pregunta_es="Clasifica estas fuentes en primarias y secundarias: un diario escrito en 1918, una página web sobre la gripe de 1918 escrita el año pasado, una foto de un hospital en 1918 y un capítulo de libro de texto sobre los años 1900. Después explica la regla que usaste.",
    pista="Primary: the 1918 diary and the 1918 photo, because they were made by people who were there at the time. Secondary: the website and the textbook chapter, because they were made later by people who studied other sources. The rule: ask when it was made and whether the person was there."),
  mdc=dict(pregunta="Choose three things to put in a time capsule for 2076. For each one, explain what a historian could learn from it and one thing it could NOT show about your life.",
    pregunta_es="Elige tres cosas para poner en una cápsula del tiempo para 2076. Para cada una, explica qué podría aprender un historiador y una cosa que NO podría mostrar sobre tu vida.",
    pista="Example: a school lunch menu shows what food the school served, but not whether students liked it. A photo of your class shows clothes and faces, but not what people were thinking. A letter shows your perspective, but not everyone's. Every source has limits, so historians need many of them."),
  pausa=dict(emoji="🏺", arte="Visual arts · VA:Cn11.1.6",
    intro="In a museum, every artifact has a small label next to it. The label tells visitors what the object is, when it was made and why it matters. Imagine that the cassette tape from the time capsule is now in a museum.",
    intro_es="En un museo, cada artefacto tiene al lado una pequeña etiqueta. La etiqueta les dice a los visitantes qué es el objeto, cuándo se hizo y por qué es importante. Imagina que el casete de la cápsula del tiempo ahora está en un museo.",
    preguntas=[("Write a museum label for the cassette tape in three sentences: what it is, when people used it and what it tells us about life in 1976.","Escribe una etiqueta de museo para el casete en tres oraciones: qué es, cuándo lo usaba la gente y qué nos dice sobre la vida en 1976."),
               ("Choose one object you use every day. If it were in a museum 100 years from now, what would its label say about our time?","Elige un objeto que usas todos los días. Si estuviera en un museo dentro de 100 años, ¿qué diría su etiqueta sobre nuestra época?")],
    pista="Example label: \"Cassette tape, used from about the 1970s to the 1990s. People recorded music and voices on a thin magnetic ribbon and played it in a cassette player. It shows that in 1976, people carried music with them, but they could not choose any song in a second, as we can today.\" Objects tell stories about changing times, tools and habits, just as works of art do.")),

dict(area="sociales", n=2, slug="mesopotamia", std="SS.6-8.G.4 · SS.6-8.G.7",
  std_texto="explain how people interact with and change their environment, and how the environment affects where people settle.",
  titulo="The river that gave and took", titulo_es="El río que daba y quitaba",
  entrada="A story about Mesopotamia, the land between two rivers, and how people changed it.",
  entrada_es="Un cuento sobre Mesopotamia, la tierra entre dos ríos, y cómo la gente la transformó.",
  tema="Rivers shaped where and how people lived in Mesopotamia", tema_es="Los ríos decidieron dónde y cómo vivía la gente en Mesopotamia",
  descripcion="A Grade 6 social studies story: farmers in Mesopotamia used the Tigris and Euphrates rivers, built canals and cities, and changed their environment. With key words, glossary, questions, an art connection and optional help in Spanish.",
  alt="In a museum of ancient cultures, Ms. Haddad points at a giant stone statue of a winged bull with a human head, while Israel and Sophia look at a small clay tablet in a glass case.",
  escena=f"Inside a quiet museum hall of ancient cultures in Chicago: a giant stone statue of a winged bull with a bearded human head stands against the wall; {P_HADDAD}, points up at the statue; {ISRAEL}, and {SOPHIA}, lean toward a glass case with a small clay tablet covered in tiny wedge-shaped marks; a large painted map of two rivers in a dry land hangs on the far wall, with no words on it",
  palabras=[
    ("settle","settle","To move to a place and make a home there for a long time.","asentarse","Ir a un lugar y hacer allí un hogar por mucho tiempo."),
    ("silt","silt","Fine, rich soil that a river leaves behind after a flood.","limo","Tierra fina y fértil que deja un río después de una inundación."),
    ("irrigation","irrigation","Bringing water to crops through canals, ditches or pipes.","irrigación (riego)","Llevar agua a los cultivos por canales, zanjas o tubos."),
    ("surplus","surplus","More of something than people need right away, like extra grain.","excedente","Más de algo de lo que la gente necesita en el momento, como grano de sobra."),
    ("civilization","civilization","A large group of people with cities, a government, writing and different kinds of jobs.","civilización","Un gran grupo de personas con ciudades, gobierno, escritura y distintos tipos de trabajos."),
    ("environment","environment","The land, water, air, plants and animals around people.","medio ambiente","La tierra, el agua, el aire, las plantas y los animales que rodean a las personas.")],
  parrafos=[
    '''At the museum of ancient cultures, a stone bull with wings and a bearded human face stood taller than two basketball players. "He guarded a palace in Mesopotamia about 2,700 years ago," said Ms. Haddad. Israel stared up. "What does Mesopotamia mean?" "The land between the rivers."''',
    '''She pointed at a map on the wall. Two blue rivers, the Tigris and the Euphrates, crossed a land that was mostly dry and brown. {{a|"Hardly any rain fell there in summer," said Ms. Haddad, "so people chose to [[settle|settle]] close to the rivers. Water decided where the first towns grew."}}''',
    '''"But the rivers were tricky," she went on. "Every spring, snow melted in the mountains, and the rivers flooded. Sometimes a flood washed away a whole village." {{b|"And yet farmers were happy after floods?" asked Sophia, reading a sign. "Yes, because the water left behind a layer of [[silt|silt]], soft, rich soil that was perfect for growing barley."}}''',
    '''The farmers didn't just wait for the river. {{c|They dug long canals and ditches to carry water to their fields. This [[irrigation|irrigation]] let them grow crops even in the hottest, driest months.}} "They changed their [[environment|environment]] to survive in it," said Ms. Haddad.''',
    '''With more water, farmers grew more barley than their families could eat. {{d|"That extra food was a [[surplus|surplus]]," said Ms. Haddad. "And when not everybody had to farm, some people could become potters, weavers, builders and priests."}} Towns grew into cities like Uruk, with tens of thousands of people.''',
    '''Sophia looked at a clay tablet the size of a cookie. Tiny wedge-shaped marks covered it. "Is that writing?" "It's cuneiform, one of the first kinds of writing in the world," said Ms. Haddad. "Many early tablets are lists of barley, sheep and beer, because people needed to keep track of all that surplus." With cities, rulers, laws and writing, Mesopotamia became a [[civilization|civilization]].''',
    '''"So the rivers only gave good things?" asked Israel. Ms. Haddad shook her head. {{e|"Over hundreds of years, irrigation water left salt behind in the soil. In some places, the land became too salty to grow wheat, so farmers switched to barley, which can handle more salt."}} "The river gave," said Sophia, "and the people's changes took some of it back."''',
    '''On the bus back, Israel looked out at the Chicago River. "Did people settle here because of water too?" "Exactly," said Ms. Haddad. "And we changed our river too. Chicago once reversed its flow." Israel's eyes went wide. "Mesopotamia was cool, but that is wild."'''],
  preguntas=[
    ("a","Why did people in Mesopotamia settle close to the rivers?","¿Por qué la gente de Mesopotamia se asentó cerca de los ríos?",
     ["The rivers were full of gold and stones","Very little rain fell in the summer","The rivers kept them safe from floods"],1,
     "Hardly any rain fell in summer, so people settled close to the rivers, where there was water."),
    ("b","Why were farmers happy after a flood?","¿Por qué los campesinos se alegraban después de una inundación?",
     ["The flood left rich silt on the fields","The flood carried away all the weeds","The flood brought fish into the canals"],0,
     "The flood left behind a layer of silt, soft and rich soil that was perfect for growing barley."),
    ("c","How did irrigation help the farmers?","¿Cómo ayudó el riego a los campesinos?",
     ["It stopped the rivers from flooding","It kept the canals full of clean salt","It brought water to crops in dry months"],2,
     "Canals and ditches carried water to the fields, so farmers could grow crops even in the hottest, driest months."),
    ("d","What happened when farmers grew a surplus?","¿Qué pasó cuando los campesinos produjeron un excedente?",
     ["People left the cities to live by the rivers","Everyone had to work harder on the farms","Some people could do jobs other than farming"],2,
     "When not everybody had to farm, some people could become potters, weavers, builders and priests."),
    ("e","What problem did irrigation cause over time?","¿Qué problema causó el riego con el tiempo?",
     ["The canals dried up the two big rivers","Salt built up and harmed the soil","Too many fish swam into the fields"],1,
     "Over hundreds of years, irrigation water left salt in the soil, and some land became too salty to grow wheat.")],
  reto=dict(tipo="Cause and effect", tipo_es="Causa y efecto",
    pregunta="Make a chain of causes and effects that starts with \"Very little rain fell\" and ends with \"Cities grew.\" Use at least four links from the story.",
    pregunta_es="Haz una cadena de causas y efectos que empiece con «Casi no llovía» y termine con «Las ciudades crecieron». Usa por lo menos cuatro eslabones del cuento.",
    pista="Very little rain fell → people settled near the rivers → they dug canals for irrigation → farmers grew a surplus of barley → some people could do other jobs → cities grew. Your chain can have different words, but each link should cause the next one."),
  mdc=dict(pregunta="People in Mesopotamia and in Chicago both changed their rivers. Compare one change from each place: why did people make it, and what was one effect, good or bad?",
    pregunta_es="La gente de Mesopotamia y de Chicago transformó sus ríos. Compara un cambio de cada lugar: ¿por qué lo hicieron y cuál fue un efecto, bueno o malo?",
    pista="Mesopotamia: farmers dug irrigation canals to grow crops in the dry season; a good effect was a surplus of food, and a bad effect was salt in the soil. Chicago: the city reversed its river around 1900 so sewage would flow away from Lake Michigan, where people got drinking water; that helped Chicago, but sent the dirty water toward towns downstream. Every change to the environment has more than one effect."),
  pausa=dict(emoji="🖼️", arte="Visual arts · VA:Cn11.1.6",
    intro="Look at the Standard of Ur, a wooden box decorated more than 4,500 years ago in the city of Ur, in Mesopotamia. Look at each row, one at a time.",
    intro_es="Observa el Estandarte de Ur, una caja de madera decorada hace más de 4,500 años en la ciudad de Ur, en Mesopotamia. Mira cada fila, una por una.",
    enlace=("https://artsandculture.google.com/asset/7gGnYlXZRuvAAA","See the Standard of Ur (British Museum on Google Arts & Culture)"),
    describe="The box is covered with tiny pieces of white shell, red stone and blue lapis lazuli. One side shows war, with soldiers and chariots. The other side shows peace: rows of people bringing animals, fish and heavy bundles, and at the top, a feast with a musician playing a lyre.",
    describe_es="La caja está cubierta de trocitos de concha blanca, piedra roja y lapislázuli azul. Un lado muestra la guerra, con soldados y carros. El otro lado muestra la paz: filas de personas que traen animales, peces y bultos pesados, y arriba, un banquete con un músico que toca una lira.",
    preguntas=[("On the peace side, what are people carrying? What does that tell you about the surplus in Ur?","En el lado de la paz, ¿qué llevan las personas? ¿Qué te dice eso sobre el excedente de Ur?"),
               ("The blue lapis lazuli came from mountains far away, in what is now Afghanistan. What does that tell you about the people of Ur?","El lapislázuli azul venía de montañas lejanas, en lo que hoy es Afganistán. ¿Qué te dice eso sobre la gente de Ur?")],
    pista="People are carrying animals, fish and goods to the feast, which shows that Ur had more food and goods than people needed right away: a surplus. Because the blue stone came from far away, the people of Ur must have traded with distant places. The artist also put the most important people at the top and made them bigger, so we can see who had power.")),

dict(area="sociales", n=3, slug="nile", std="SS.6-8.H.1.LC",
  std_texto="analyze change and continuity over time, using the example of how people have lived along the Nile River from ancient Egypt to today.",
  titulo="The gift of the Nile", titulo_es="El regalo del Nilo",
  entrada="A story about ancient Egypt, the Nile River and what has changed and stayed the same.",
  entrada_es="Un cuento sobre el antiguo Egipto, el río Nilo y lo que ha cambiado y lo que sigue igual.",
  tema="Some things along the Nile changed, and some stayed the same", tema_es="Algunas cosas en el Nilo cambiaron y otras siguieron igual",
  descripcion="A Grade 6 social studies story: students compare life along the Nile in ancient Egypt and today to find change and continuity. With key words, glossary, questions, an art connection and optional help in Spanish.",
  alt="In the classroom, Ms. Haddad shows two photos side by side on a screen, an ancient wall painting of farmers and a modern farm by a river, while Salma and Elías draw a T-chart on the whiteboard.",
  escena=f"A sixth grade classroom in Chicago: a big screen shows two pictures side by side, on the left an ancient Egyptian wall painting of farmers harvesting wheat beside a river, on the right a modern green farm field beside a wide blue river with palm trees; {P_HADDAD}, stands beside the screen holding a remote; {SALMA}, and {ELIAS}, draw a large T-shaped chart on the whiteboard with simple drawings of a river, a boat and a plant, and no words",
  palabras=[
    ("change","change","When something becomes different over time.","cambio","Cuando algo se vuelve diferente con el tiempo."),
    ("continuity","continuity","When something stays the same over a long time.","continuidad","Cuando algo sigue igual durante mucho tiempo."),
    ("flood","annual flood","The time each year when a river rises and covers the land near it.","crecida anual","La época de cada año en que un río sube y cubre la tierra cercana."),
    ("shaduf","shaduf","A long pole with a bucket on one end and a weight on the other, used to lift water from a river.","shaduf (cigoñal)","Un palo largo con un balde (cubeta) en un extremo y un peso en el otro, que sirve para sacar agua del río."),
    ("dam","dam","A strong wall built across a river to hold back and control the water.","presa","Un muro fuerte construido de lado a lado de un río para retener y controlar el agua."),
    ("hieroglyphs","hieroglyphs","The writing of ancient Egypt, made of small pictures and signs.","jeroglíficos","La escritura del antiguo Egipto, hecha con dibujitos y signos.")],
  parrafos=[
    '''"Over 2,000 years ago, a Greek traveler named Herodotus called Egypt the gift of the Nile," said Ms. Haddad. She showed a photo taken from space: a long, thin green line running through a huge yellow desert. "That green line is almost all the farmland in Egypt. Today, about 95 out of every 100 Egyptians live close to the river."''',
    '''"Historians ask two questions," she said. "What changed? And what stayed the same?" {{a|She drew a T-chart on the board. One side said [[change|Change]]. The other side said [[continuity|Continuity]]. "Continuity means something that has lasted for a long, long time."}}''',
    '''On the screen appeared an ancient wall painting of farmers cutting wheat. "For thousands of years, the Nile rose every summer," said Ms. Haddad. {{b|"The [[flood|annual flood]] spread water and dark, rich mud over the fields. Egyptians even organized their calendar around it, with three seasons: the flood, the growing time and the harvest."}}''',
    '''Next came a drawing of a man pulling down a long pole with a bucket. "That's a [[shaduf|shaduf]]," said Ms. Haddad. "Farmers used it to lift water from the river to their fields." {{c|Then she showed a modern photo of a farmer using the same kind of pole. "Some farmers still use one today." Elías wrote shaduf on the Continuity side.}}''',
    '''"Then, in the 1960s, Egypt built the Aswan High [[dam|Dam]]," said Ms. Haddad. {{d|"Since it was finished in 1970, the Nile no longer floods every summer. The dam stores water for dry years and makes electricity, but the rich mud no longer reaches the fields, so farmers now buy fertilizer."}} Salma wrote the dam on the Change side, with two arrows: one good, one bad.''',
    '''"What about writing?" asked Salma. "Ancient Egyptians wrote with [[hieroglyphs|hieroglyphs]]," said Ms. Haddad, "but today Egyptians speak and write Arabic. For a long time, nobody could read hieroglyphs at all, until scholars cracked the code about 200 years ago." Salma added writing to the Change side.''',
    '''By the end of class, the chart was full. Change: the flood stopped, people use tractors and phones, the language is different. Continuity: people still live along the river, still farm wheat, and still sail boats on the Nile. {{e|"So history isn't only about what changed," said Elías. "It's also about what lasted." "And why it lasted," said Ms. Haddad. "The Nile is still the reason people live there."}}''',
    '''As they packed up, Elías looked at his water bottle. "Lake Michigan is our Nile," he said. "Everything in Chicago depends on it." "Then you just found continuity in your own city," said Ms. Haddad.'''],
  preguntas=[
    ("a","What does continuity mean?","¿Qué significa continuidad?",
     ["Something that lasts for a long time","Something that changes every year","Something that happened only once"],0,
     "Ms. Haddad says continuity means something that has lasted for a long, long time."),
    ("b","Why was the annual flood important to ancient Egyptians?","¿Por qué la crecida anual era importante para los antiguos egipcios?",
     ["It washed the cities clean every year","It spread water and rich mud on fields","It kept enemies away from the river"],1,
     "The annual flood spread water and dark, rich mud over the fields, and Egyptians even organized their calendar around it."),
    ("c","Why did Elías put the shaduf on the Continuity side?","¿Por qué Elías puso el shaduf del lado de la continuidad?",
     ["It was invented only a few years ago","It was the most important invention","Some farmers still use one today"],2,
     "Farmers used the shaduf in ancient times, and some farmers still use the same kind of pole today."),
    ("d","What was one change caused by the Aswan High Dam?","¿Cuál fue un cambio causado por la gran presa de Asuán?",
     ["The Nile began to flood twice a year","The Nile stopped flooding every summer","Farmers stopped growing wheat forever"],1,
     "Since the dam was finished in 1970, the Nile no longer floods every summer, and the rich mud no longer reaches the fields."),
    ("e","What did Elías learn about history?","¿Qué aprendió Elías sobre la historia?",
     ["It is mostly about what changed","It is only about kings and pyramids","It is also about what lasted"],2,
     "Elías realized that history isn't only about what changed; it's also about what lasted.")],
  reto=dict(tipo="Change and continuity", tipo_es="Cambio y continuidad",
    pregunta="Make your own T-chart about your family or your neighborhood. Write two things that changed and two things that stayed the same over the last 30 years. Then explain why one of the things lasted.",
    pregunta_es="Haz tu propia tabla en T sobre tu familia o tu barrio. Escribe dos cosas que cambiaron y dos que siguieron igual en los últimos 30 años. Después explica por qué una de esas cosas se mantuvo.",
    pista="Example. Change: people now pay with phones, and the old movie theater closed. Continuity: families still shop at the same market, and the neighborhood still celebrates the same festival. Something often lasts because people still need it or because it is important to who they are."),
  mdc=dict(pregunta="The Aswan High Dam brought good and bad effects. Was it a good change for Egypt overall? Give one reason for and one reason against, then decide.",
    pregunta_es="La gran presa de Asuán trajo efectos buenos y malos. ¿Fue un buen cambio para Egipto en general? Da una razón a favor y una en contra, y después decide.",
    pista="For: the dam stores water for dry years, prevents dangerous floods and makes electricity. Against: the rich mud no longer reaches the fields, so farmers must buy fertilizer. Historians often say a change was good for some people and bad for others. Your decision is fine if you support it with evidence."),
  pausa=dict(emoji="🖼️", arte="Visual arts · VA:Cn11.1.6",
    intro="Look at this small blue hippopotamus. It was made in Egypt nearly 4,000 years ago and placed in a tomb. Today, museum visitors call it William.",
    intro_es="Observa este pequeño hipopótamo azul. Se hizo en Egipto hace casi 4,000 años y se colocó en una tumba. Hoy, los visitantes del museo lo llaman William.",
    enlace=("https://www.metmuseum.org/art/collection/search/544227","See the hippopotamus (The Metropolitan Museum of Art)"),
    describe="A bright blue hippo stands on four short legs. Dark drawings of lotus flowers, leaves and buds cover its body, as if the hippo were standing in the plants of the river.",
    describe_es="Un hipopótamo azul brillante está de pie sobre cuatro patas cortas. Por todo su cuerpo hay dibujos oscuros de flores de loto, hojas y capullos, como si el hipopótamo estuviera entre las plantas del río.",
    preguntas=[("Why do you think the artist painted river plants on the hippo?","¿Por qué crees que el artista pintó plantas del río sobre el hipopótamo?"),
               ("Real hippos were dangerous to people on the Nile. How can one animal show that the river was both a gift and a danger?","Los hipopótamos de verdad eran peligrosos para la gente del Nilo. ¿Cómo puede un animal mostrar que el río era a la vez un regalo y un peligro?")],
    pista="The lotus flowers show where the hippo lived: in the Nile, among its plants. The blue color can remind us of water. Long ago, someone broke three of this hippo's legs on purpose, so it could not hurt the person in the tomb; museum experts later repaired them. The river gave Egyptians food, water and rich mud, but it also had dangerous floods and dangerous animals. Art from the past is a primary source: it shows what people saw and what was important to them.")),

dict(area="sociales", n=4, slug="athens", std="SS.6-8.CV.4.LC · SS.6-8.H.2.LC",
  std_texto="describe democratic principles in ancient Athens and today, and explain how ideas about who can take part in government have changed over time.",
  titulo="Everybody votes?", titulo_es="¿Todos votan?",
  entrada="A story about a class election and the first democracy in ancient Athens.",
  entrada_es="Un cuento sobre una elección en la clase y la primera democracia, en la antigua Atenas.",
  tema="Democracy began in Athens, and the idea of who votes grew", tema_es="La democracia nació en Atenas, y la idea de quién vota creció",
  descripcion="A Grade 6 social studies story: a class election leads students to compare democracy in ancient Athens with democracy today. With key words, glossary, questions, an art connection and optional help in Spanish.",
  alt="In the classroom, students raise their hands to vote while Athena counts and Daniel holds up a broken piece of pottery; Ms. Haddad stands next to a drawing of an ancient hill with a crowd.",
  escena=f"A cheerful sixth grade classroom in Chicago during a vote: many students raise their hands; {ATHENA}, counts the raised hands, pointing with a pencil; {DANIEL}, holds up a small broken piece of reddish pottery and grins; {P_HADDAD}, stands beside a large poster with a drawing of a crowd of people in ancient Greek robes on a rocky hill, with no words on the poster",
  palabras=[
    ("democracy","democracy","A government in which the people hold the power and make decisions by voting.","democracia","Un gobierno en el que el pueblo tiene el poder y toma decisiones votando."),
    ("citizen","citizen","A member of a country or city who has rights and responsibilities there.","ciudadano o ciudadana","Miembro de un país o de una ciudad, con derechos y responsabilidades allí."),
    ("direct","direct democracy","A democracy in which citizens vote on every law themselves.","democracia directa","Una democracia en la que los ciudadanos votan ellos mismos cada ley."),
    ("representative","representative democracy","A democracy in which citizens elect people to make laws for them.","democracia representativa","Una democracia en la que los ciudadanos eligen a personas que hacen las leyes por ellos."),
    ("assembly","assembly","A big meeting where people gather to discuss and vote.","asamblea","Una reunión grande en la que la gente se junta para hablar y votar."),
    ("ostracism","ostracism","In ancient Athens, a vote to send a powerful person away from the city for ten years.","ostracismo","En la antigua Atenas, una votación para expulsar de la ciudad por diez años a una persona poderosa.")],
  parrafos=[
    '''The class had to choose a theme for the spring field day. "Raise your hand for Ancient Olympics," said Athena, who was in charge of counting. Fourteen hands went up. "Raise your hand for Superheroes." Eleven hands. "Ancient Olympics wins!" Daniel groaned, but he clapped anyway.''',
    '''"You just did something people invented in Athens, Greece, about 2,500 years ago," said Ms. Haddad. {{a|"It's called [[democracy|democracy]]. The word comes from two Greek words: demos, the people, and kratos, power. The people have the power."}}''',
    '''She showed a drawing of a rocky hill packed with people. "Athenian [[citizen|citizens]] met on this hill in an [[assembly|assembly]], about forty times a year. Thousands came. Anyone could stand up and speak, and they voted by raising their hands." {{b|"Just like us!" said Athena. "Yes. They voted on the laws themselves. That is called [[direct|direct democracy]]."}}''',
    '''"Could we do that in the United States?" asked Daniel. "There are more than 300 million of us," said Ms. Haddad. "We'd never fit on a hill." {{c|"So instead, we elect people, like senators and representatives in Congress, to make laws for us. That's a [[representative|representative democracy]]."}}''',
    '''Daniel held up a broken piece of pottery he had made in art class. "Athenians had a strange kind of vote," said Ms. Haddad. {{d|"If citizens worried that a person was becoming too powerful, they could scratch his name on a piece of broken pottery. If enough people wrote the same name, he had to leave Athens for ten years. That was called [[ostracism|ostracism]]."}} "So they could kick out a bully," said Daniel. "A powerful one, yes."''',
    '''"Then Athens was totally fair," said Athena. Ms. Haddad raised an eyebrow. {{e|"Not exactly. Only free adult men whose parents were both Athenian could vote. Women couldn't vote. Enslaved people couldn't vote. People born in other cities couldn't vote, even if they had lived in Athens all their lives."}} The room went quiet. "So most people didn't vote," said Athena slowly.''',
    '''"Ideas about who should vote have changed over time," said Ms. Haddad. "In the United States, women won the right to vote across the country in 1920, and the Voting Rights Act of 1965 protected the vote for African Americans who had been blocked. Each time, people had to argue and work for that change."''',
    '''Athena looked at the board. Fourteen to eleven. "Maybe next time we should ask the other sixth grade class too," she said. "Field day is theirs too." Daniel nodded. "And maybe they like superheroes."'''],
  preguntas=[
    ("a","What does the word democracy mean?","¿Qué significa la palabra democracia?",
     ["The people have the power","The best leader has the power","The richest family has the power"],0,
     "Democracy comes from demos, the people, and kratos, power: the people have the power."),
    ("b","Why was Athens a direct democracy?","¿Por qué Atenas era una democracia directa?",
     ["Leaders chose the laws without asking","Citizens voted on the laws themselves","Only judges could change the laws"],1,
     "In the assembly, Athenian citizens voted on the laws themselves, which is a direct democracy."),
    ("c","Why does the United States use representative democracy?","¿Por qué Estados Unidos usa la democracia representativa?",
     ["People in the United States don't like voting","The Constitution forbids big meetings","It has too many people to meet in one place"],2,
     "There are more than 300 million people, so citizens elect representatives to make laws for them."),
    ("d","What was the purpose of ostracism?","¿Cuál era el propósito del ostracismo?",
     ["To choose the next leader of the city","To stop a person who was getting too powerful","To decide who could make pottery"],1,
     "If citizens worried that a person was becoming too powerful, they could vote to send him away for ten years."),
    ("e","Why was Athens not fair to everyone?","¿Por qué Atenas no era justa con todos?",
     ["The assembly met only once every year","Votes were counted by only one person","Most people living there could not vote"],2,
     "Only free adult men whose parents were both Athenian could vote; women, enslaved people and people from other cities could not.")],
  reto=dict(tipo="Compare and contrast", tipo_es="Compara y contrasta",
    pregunta="Compare democracy in ancient Athens with democracy in the United States today. Give one way they are alike and two ways they are different, using details from the story.",
    pregunta_es="Compara la democracia de la antigua Atenas con la de Estados Unidos hoy. Da una semejanza y dos diferencias, con detalles del cuento.",
    pista="Alike: in both, citizens hold the power and vote. Different: Athens was a direct democracy where citizens voted on laws themselves, and the United States is a representative democracy where people elect others to make laws. Also, in Athens only free men with Athenian parents could vote, and today all adult citizens can vote."),
  mdc=dict(pregunta="Ostracism was a way to protect democracy from someone too powerful. What ways does the United States use today to keep one person from getting too much power? Is that better or worse than ostracism? Explain.",
    pregunta_es="El ostracismo era una forma de proteger la democracia de alguien demasiado poderoso. ¿Qué formas usa Estados Unidos hoy para evitar que una persona tenga demasiado poder? ¿Es mejor o peor que el ostracismo? Explica.",
    pista="Today the United States uses regular elections, term limits for the president (two terms) and checks and balances, so Congress, the president and the courts can each limit the others. One reason it may be better: it does not punish a person just because people are afraid of them. One reason ostracism was interesting: citizens could act directly. Any answer works if you give reasons."),
  pausa=dict(emoji="🪙", arte="Visual arts · VA:Cn11.1.6",
    intro="Look at a silver coin made in Athens around 450 years before the Common Era. Athenians used coins like this to buy and sell.",
    intro_es="Observa una moneda de plata hecha en Atenas alrededor del año 450 antes de nuestra era. Los atenienses usaban monedas así para comprar y vender.",
    enlace=("https://www.metmuseum.org/art/collection/search/254721","See the coin (The Metropolitan Museum of Art)"),
    describe="One side shows the head of the goddess Athena wearing a helmet. The other side shows an owl with big round eyes, a small branch of olive leaves and three Greek letters that stand for the Athenians.",
    describe_es="Un lado muestra la cabeza de la diosa Atenea con casco. El otro lado muestra un búho de ojos grandes y redondos, una ramita de olivo y tres letras griegas que significan «de los atenienses».",
    preguntas=[("Why do you think the people of Athens put their goddess and the owl on their money?","¿Por qué crees que la gente de Atenas puso a su diosa y al búho en su dinero?"),
               ("What pictures and words are on United States coins and bills? What do they tell people about the country?","¿Qué imágenes y palabras hay en las monedas y billetes de Estados Unidos? ¿Qué le dicen a la gente sobre el país?")],
    pista="Athena was the protector of the city, the city was named after her, and the owl was her symbol. Putting them on coins told everyone, even far away, that this money came from Athens and that the city was proud and strong. United States money shows presidents, buildings, an eagle and words like \"Liberty\" and \"E pluribus unum,\" which tell people what the country values.")),
]
